const span = { lo: 0, hi: 0 };
let held = 11;
const next = (): number => { held = (held * 1103515245 + 12345) % 2147483648; return held / 2147483648; };
const together = Array.from({ length: 32 }, (_, i) => ({ origin: `o${i}`, epoch: 8, span }));
const strewn = Array.from({ length: 32 }, (_, i) => ({ origin: `o${i}`, epoch: Math.floor(next() * 8), span }));

console.log('in phase  ', interfere(together, 8), 'coherence', coherence(together, 8).toFixed(2));
console.log('strewn    ', interfere(strewn, 8).toFixed(0), 'coherence', coherence(strewn, 8).toFixed(2));
console.log('their number is 32, and its square is', 32 ** 2);
console.log('why       claims that land at one turn of the period add as the square of their number, and the same claims strewn across it add as its order');
"

bound-lock/1 at=place: by=reader form=alphabet measure=source role=reads scope=examples/price value="import { chain, disagree, freedom, meetAt, origins, point, unit } from '@lapxo/obligations';

const said = (cell: Parameters<typeof meetAt>[0]): string =>
  (origins(cell) < 2 ? 'grey' : disagree(cell) ? 'split' : 'agreed');

const price = point('price', 0, [
  { origin: 'seller', span: { lo: 2, hi: 9 } },
  { origin: 'buyer', span: { lo: 5, hi: 12 } },
]);
const scale = chain(Array.from({ length: 16 }, (_, i) => `l${i}`));

console.log('verdict   ', said(price));
console.log('they hold ', JSON.stringify(meetAt(price)));
console.log('still free', freedom(scale, unit('price', { floor: 'l5', ceiling: 'l9' })).toFixed(2), 'bits');
console.log('why       a seller and a buyer are two origins; where their marks meet is a price, and what is left between the marks is what nobody has decided yet');
"

bound-lock/1 at=place: by=reader form=alphabet measure=source role=reads scope=examples/signature value="import { intervals } from '@lapxo/obligations/forms';
import { cell, meet, sign } from '@lapxo/obligations/views/field';

const scale = intervals(0, 100);
const world = [0, 1, 2, 3].map((i) => cell(`c${i}`, 0, [{ origin: `own${i}`, span: { lo: 20 * i, hi: 100 } }], ['ceiling']));
const before = new Map([['ceiling', cell<{ lo: number; hi: number }>('ceiling')]]);
const after = sign(scale, before, 'ceiling', { lo: 0, hi: 45 });

console.log('cells resting on the ceiling', world.filter((one) => one.restsOn.includes('ceiling')).length);
for (const [i, one] of world.entries()) {
  console.log(`c${i} before`, JSON.stringify(meet(scale, one, before)), '· after', JSON.stringify(meet(scale, one, after)));
}
console.log('claims edited by the signature', world.flatMap((one) => one.seen).filter((claim) => claim.span.hi !== 100).length);
console.log('why       one signature narrows a bound and every cell resting on it reads the narrower one, without touching a single claim any origin made');
"

bound-lock/1 at=place: by=reader form=alphabet measure=source role=reads scope=examples/thermometer value="import { disagree, origins, point } from '@lapxo/obligations';
import { steady } from '@lapxo/obligations/views/product';

const said = (cell: ReturnType<typeof point>): string =>
  (origins(cell) < 2 ? 'grey' : disagree(cell) ? 'split' : 'agreed');

const bath = point('bath', 0, [
  { origin: 'a', span: { lo: 19.8, hi: 20.2 } },
  { origin: 'b', span: { lo: 19.9, hi: 20.3 } },
  { origin: 'c', span: { lo: 19.7, hi: 20.1 } },
  { origin: 'd', span: { lo: 24.0, hi: 24.4 } },
]);
const without = (name: string) => point('bath', 0, bath.seen.filter((one) => one.origin !== name));

console.log('four thermometers', said(bath));
for (const one of ['a', 'b', 'c', 'd']) console.log(`without ${one}        `, said(without(one)));
console.log('holds without any one of them:', steady(bath));
console.log('why       leaving one out names the instrument that disagrees, and a verdict that needs every origin is not a verdict');
"

bound-lock/1 at=place: by=reader form=alphabet measure=source role=reads scope=examples/withdrawal value="import { intervals } from '@lapxo/obligations/forms';
import { cell, encounter, meet, observe } from '@lapxo/obligations/views/field';

const scale = intervals(0, 20);
const held = cell('x', 0, [{ id: 'k1', origin: 'a', span: { lo: 2, hi: 9 } }, { id: 'k2', origin: 'b', span: { lo: 5, hi: 12 } }]);
const back = observe(held, { origin: 'b', span: { lo: 5, hi: 12 }, takes: 'k2' });

console.log('two origins ', encounter(scale, held).origins, JSON.stringify(meet(scale, held)));
console.log('b takes k2  ', encounter(scale, back).origins, JSON.stringify(meet(scale, back)));
console.log('claims kept ', back.seen.length);
console.log('why       a withdrawal names the claim it takes back, so the cell returns to one origin while all three claims stay on it and nothing is matched by looking like something');
"

